const char *path = "/var/s.link";
ssize_t len;
char *list_buffer = NULL;

// 1. Get required size (attributes of the link itself)
len = llistxattr(path, NULL, 0);

if (len > 0) {
    list_buffer = malloc(len);
    // 2. Retrieve attribute names into buffer
    len = llistxattr(path, list_buffer, len);

    // list_buffer holds null-separated names
}

free(list_buffer);
